// Temporary pre-merge harness contract. Remove alongside auto-qa-smoke.yml.
const assert = require("node:assert/strict");
const { createHash } = require("node:crypto");
const { readFileSync } = require("node:fs");
const { join } = require("node:path");
const { test } = require("node:test");

const read = (file) =>
  readFileSync(join(__dirname, "../workflows", file), "utf8");
const source = read("auto-qa.md");
const normal = read("auto-qa.lock.yml");
const harness = read("auto-qa-smoke.yml");
const sha256 = (text) => createHash("sha256").update(text).digest("hex");

// Enumerate every permitted deviation from the reviewed normal workflow.
const proxyImage = "ghcr.io/github/gh-aw-mcpg:v0.5.0";
const pinnedProxyImage =
  `${proxyImage}@sha256:` +
  "d3544a4222e7efeeeb38669d8a1af0c72691c55b8f6506b15aa5920f7f31b7bc";
const pinProxy = (text) =>
  text.replace(
    `CLI_PROXY_IMAGE: '${proxyImage}'`,
    `CLI_PROXY_IMAGE: '${pinnedProxyImage}'`,
  );
const changes = [
  [
    `CLI_PROXY_IMAGE: '${proxyImage}'`,
    `CLI_PROXY_IMAGE: '${pinnedProxyImage}'`,
  ],
  [
    "# This file was automatically generated by gh-aw (v1.0.1). DO NOT EDIT.",
    "# TEMPORARY TEST HARNESS: remove before requesting review/merging.\n" +
      "# Derived from auto-qa.lock.yml at e3b28200bd66b2ffd1fd0ba609711206915236b7.\n" +
      "# Only the test envelope, immutable metadata checkout and CLI-proxy pin differ.\n" +
      "# Production auto-qa.md / auto-qa.lock.yml remain unchanged.\n" +
      "# Original generation notice: This file was automatically generated by gh-aw (v1.0.1). DO NOT EDIT.",
  ],
  ['name: "Auto QA"\non:', 'name: "Auto QA smoke test (temporary)"\non:'],
  [
    '  group: auto-qa-${{ github.event.pull_request.number }}\n\nrun-name: "Auto QA"',
    '  group: auto-qa-smoke-${{ github.event.pull_request.number }}\n\nrun-name: "Auto QA smoke test (temporary)"',
  ],
  [
    "          ref: ${{ (github.event_name == 'pull_request' || github.event_name == 'pull_request_review' || github.event_name == 'pull_request_review_comment') && github.event.pull_request != null && github.event.pull_request.base.sha || github.sha }}",
    "          ref: e3b28200bd66b2ffd1fd0ba609711206915236b7",
  ],
  [
    "          fetch-depth: 1\n      - name: Save agent config folders for base branch restoration",
    "          fetch-depth: 1\n" +
      "      - name: Verify the reviewed workflow source and lock\n" +
      "        shell: bash\n" +
      "        run: |\n" +
      "          sha256sum --check <<'SHA256'\n" +
      "          9e52456959fdd2a44fe44f5610252f53f3e6ca2b9d9df75cae9569e0688262fc  .github/workflows/auto-qa.md\n" +
      "          70244832b9484029a37887c7d53cf83ea4a2f5946952bdeeec701b349c2c9e77  .github/workflows/auto-qa.lock.yml\n" +
      "          SHA256\n" +
      "      - name: Save agent config folders for base branch restoration",
  ],
  [
    "    if: >\n      (github.event.label == null || github.event.label.name == 'auto-qa') && (((github.event.pull_request.state == 'open' &&",
    "    if: >\n" +
      "      github.repository == 'canonical/snapcraft.io' &&\n" +
      "      github.event.pull_request.number == 5974 &&\n" +
      "      github.event.pull_request.head.ref == 'feat/auto-qa-pr-browser-checks' &&\n" +
      "      github.event.label.name == 'auto-qa-smoke' && (((github.event.pull_request.state == 'open' &&",
  ],
];

test("production source and compiled workflow are the reviewed immutable inputs", () => {
  assert.equal(
    sha256(source),
    "9e52456959fdd2a44fe44f5610252f53f3e6ca2b9d9df75cae9569e0688262fc",
  );
  assert.equal(
    sha256(normal),
    "70244832b9484029a37887c7d53cf83ea4a2f5946952bdeeec701b349c2c9e77",
  );
});

test("the entire temporary harness differs only by its pinned test envelope", () => {
  let expected = normal;
  for (const [before, after] of changes) {
    assert.equal(
      expected.split(before).length,
      2,
      "Each permitted change must have exactly one source match",
    );
    expected = expected.replace(before, after);
  }
  assert.equal(harness, expected);
});

test("proxy startup uses the manifest digest instead of a mutable tag alias", () => {
  const manifest = JSON.parse(
    normal.split("# gh-aw-manifest: ")[1].split("\n")[0],
  );
  assert.equal(
    manifest.containers.find(({ image }) => image === proxyImage).pinned_image,
    pinnedProxyImage,
  );
  assert.ok(harness.includes(`CLI_PROXY_IMAGE: '${pinnedProxyImage}'`));
  assert.ok(!harness.includes(`CLI_PROXY_IMAGE: '${proxyImage}'`));
});

test("runtime is byte-preserved except for the explicit proxy digest pin", () => {
  const from = (text, start, end) => text.split(start)[1].split(end)[0];
  assert.equal(
    from(harness, "  agent:\n", "  conclusion:\n"),
    pinProxy(from(normal, "  agent:\n", "  conclusion:\n")),
  );
  assert.equal(
    from(harness, "  detection:\n", "  pre_activation:\n"),
    from(normal, "  detection:\n", "  pre_activation:\n"),
  );
  assert.equal(
    harness.split("  safe_outputs:\n")[1],
    normal.split("  safe_outputs:\n")[1],
  );
  assert.match(harness, /runtime-import \.github\/workflows\/auto-qa\.md/);
  assert.doesNotMatch(harness, /workflow_dispatch:|pull_request_target:/);
});
